//autogenerated:yes
//nolint:revive,govet,errcheck
package marsh_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/marsh"
	"github.com/stretchr/testify/require"
)

func TestEnum_MARSH_MANUAL_SETPOINT_MODE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MARSH_MANUAL_SETPOINT_MODE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MARSH_MANUAL_SETPOINT_MODE_TARGET.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MARSH_MANUAL_SETPOINT_MODE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MARSH_MANUAL_SETPOINT_MODE_TARGET, dec)
	})
}
